package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    attribute previousIo0 : Boolean := false;
    attribute flashing : Boolean := false;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousIo0))) {
        first start;
        then assign flashing := (not flashing);
      }
      then assign previousIo0 := io_0;
    }
    out attribute io_1 : Boolean = false;
  }
  part system : Controller;
}
